# November 19, 2026: Albany County outside the city, second pass: the hilltowns (Knox, Westerlo, Rensselaerville's
# Preston Hollow), New Scotland (Clarksville, Feura Bush, Slingerlands side of the rail trail), Coeymans Landing and
# Coeymans Hollow, and Altamont's old business street. Drawn at random by tools/choose.py --state ny (region albco).
# All standing buildings: the county's ruins were already on the map. Sources opened in this session: Wikipedia as raw
# text (tools/wiki_raw.py), HMdb marker pages (tools/page.py), the National Register forms for the Coeymans Landing
# Historic District (100001767) and the McCarty Stone Cottage (15000474) (text layers read), the Altamont Enterprise,
# U.W. Marx, NYS Parks and Ravena Coeymans Historical Society pages (page.py), and albanyhilltowns.com pages (the web
# fetch tool, through a helper).
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HM(t,n): return ['HMdb: '+t,'https://www.hmdb.org/m.asp?m=%d'%n]
